# vim: set noexpandtab: -*- indent-tabs-mode: t -*-
"""B-repr(B5) §3.2/§3.3 API signature probes — PERMANENT regressions.

Maintainer requirement (B5 design review, 2026-07-23): every Drift-side
API signature pinned by the B5 checkpoint must be COMPILE-PROVEN against
the current language substrate BEFORE implementation GO, and the
accepted probes must remain as regressions (never deleted).

The probe module below proves, end to end (compile + link + run):
  * `require F is core.Fn1..Fn4` / `core.FnThrow1..4` bounds over
    `mem.Ptr<Byte>` (with_bytes / checked with_cstr arities /
    unsafe variants / throwing variants);
  * `pub variant CStringError { InteriorNul(arg: Int, index: Int) }`
    and `core.Result<T, CStringError>` returns;
  * move-only owned-handle structs with `implement core.Destructible`
    (consuming `var self` destroy), a consuming `release(var self)`
    using the nullable-field pattern (`mem.replace` + `ptr_is_null`
    guard — no forget/into_raw intrinsic needed), and the
    `ReleasedCBytes {ptr, len}` released-value type (declared Copy);
  * `CArgv`-shaped declared-Copy struct (non-owning scope view) with
    public getters, and public getters on `ReleasedCBytes` /
    `OwnedCStr.get()` / `OwnedCBytes.get()` borrowed views;
  * `with_cstring_scope` where the HELPER retains ownership of the
    scope and the body receives `&mut CStringScope` (`core.Fn1<&mut
    …>` / `core.FnThrow1<&mut …>` bounds — maintainer ruling; the
    scope's Destructible cleanup runs in the helper after the body
    returns), in nothrow and throwing forms;
  * explicit-generic call syntax `<type T, F>`.

LANGUAGE_BUG (FIXED) discovered by these probes: a nested call in
method-call argument position (`body.call(probe_ptr(&b))`) was
silently typed Unknown by the `defer_infer_diag` early bail in
`checker/call_resolver.py`, failing require-bound unification.  Fixed
via the transactional deferred-resolution attempt; pinned separately
by `test_nested_call_arg_defer_infer_regression.py`.  These probes
now exercise the helper-returned-Ptr path DIRECTLY (`probe_ptr`), no
inline workaround.
"""
from __future__ import annotations

import subprocess
import sys
from pathlib import Path

from lang.codegen.llvm.test_utils import sanitizer_timeout

ROOT = Path(__file__).resolve().parents[3]

PROBE_SRC = 'module main;\n\nimport std.core as core;\nimport std.mem as mem;\n\n// ── B5 §3.2/3.3 signature probes v2 (all promised families) ──\n\npub variant CStringError {\n\tInteriorNul(arg: Int, index: Int)\n}\n\nfn zero_byte() nothrow -> Byte {\n\treturn core.string_byte_at("z", 0);\n}\n\n// Helper-returned Ptr — exercises the defer-infer LANGUAGE_BUG fix.\nfn probe_ptr(b: &Byte) nothrow -> mem.Ptr<Byte> {\n\treturn unsafe { mem.ptr_from_ref<type Byte>(b) };\n}\n\n// with_bytes — nothrow + throwing\npub fn with_bytes_probe<T, F>(s: &String, body: F) nothrow -> T require F is core.Fn2<mem.Ptr<Byte>, Int, T> {\n\tval b = zero_byte();\n\treturn body.call(probe_ptr(b), s.byte_length());\n}\n\npub fn with_bytes_throw_probe<T, F>(s: &String, body: F) -> T require F is core.FnThrow2<mem.Ptr<Byte>, Int, T> {\n\tval b = zero_byte();\n\treturn body.call(probe_ptr(b), s.byte_length());\n}\n\n// checked nothrow arities 1..4\npub fn with_cstr_probe<T, F>(a: &String, body: F) nothrow -> core.Result<T, CStringError> require F is core.Fn1<mem.Ptr<Byte>, T> {\n\tval b = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(b)));\n}\n\npub fn with_cstr2_probe<T, F>(a: &String, b: &String, body: F) nothrow -> core.Result<T, CStringError> require F is core.Fn2<mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x)));\n}\n\npub fn with_cstr3_probe<T, F>(a: &String, b: &String, c: &String, body: F) nothrow -> core.Result<T, CStringError> require F is core.Fn3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x)));\n}\n\npub fn with_cstr4_probe<T, F>(a: &String, b: &String, c: &String, d: &String, body: F) nothrow -> core.Result<T, CStringError> require F is core.Fn4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x), probe_ptr(x)));\n}\n\n// checked THROWING arities 1..4 (complete family)\npub fn with_cstr_throw_probe<T, F>(a: &String, body: F) -> core.Result<T, CStringError> require F is core.FnThrow1<mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x)));\n}\n\npub fn with_cstr2_throw_probe<T, F>(a: &String, b: &String, body: F) -> core.Result<T, CStringError> require F is core.FnThrow2<mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x)));\n}\n\npub fn with_cstr3_throw_probe<T, F>(a: &String, b: &String, c: &String, body: F) -> core.Result<T, CStringError> require F is core.FnThrow3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x)));\n}\n\npub fn with_cstr4_throw_probe<T, F>(a: &String, b: &String, c: &String, d: &String, body: F) -> core.Result<T, CStringError> require F is core.FnThrow4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn core.Result::Ok(body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x), probe_ptr(x)));\n}\n\n// unsafe no-scan arities 1..4 (complete family)\npub fn with_cstr_unsafe_probe<T, F>(a: &String, body: F) nothrow -> T require F is core.Fn1<mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn body.call(probe_ptr(x));\n}\n\npub fn with_cstr2_unsafe_probe<T, F>(a: &String, b: &String, body: F) nothrow -> T require F is core.Fn2<mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn body.call(probe_ptr(x), probe_ptr(x));\n}\n\npub fn with_cstr3_unsafe_probe<T, F>(a: &String, b: &String, c: &String, body: F) nothrow -> T require F is core.Fn3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x));\n}\n\npub fn with_cstr4_unsafe_probe<T, F>(a: &String, b: &String, c: &String, d: &String, body: F) nothrow -> T require F is core.Fn4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, T> {\n\tval x = zero_byte();\n\treturn body.call(probe_ptr(x), probe_ptr(x), probe_ptr(x), probe_ptr(x));\n}\n\n// ── Owned handoff types (getters pinned) ──\n\npub struct OwnedCStrProbe {\n\tptr: mem.Ptr<Byte>\n}\n\nimplement core.Destructible for OwnedCStrProbe {\n\tpub fn destroy(var self: OwnedCStrProbe) nothrow -> Void {\n\t\tval is_null = unsafe { mem.ptr_is_null<type Byte>(self.ptr) };\n\t\tif is_null {\n\t\t\treturn;\n\t\t}\n\t}\n}\n\nimplement OwnedCStrProbe {\n\tpub fn get(self: &OwnedCStrProbe) nothrow -> mem.Ptr<Byte> {\n\t\treturn self.ptr;\n\t}\n\tpub fn release(var self: OwnedCStrProbe) nothrow -> mem.Ptr<Byte> {\n\t\tvar drained = mem.rawbuffer_empty<type Byte>();\n\t\tval null_ptr = mem.rawbuffer_ptr<type Byte>(drained);\n\t\tval out = mem.replace<type mem.Ptr<Byte> >(self.ptr, null_ptr);\n\t\treturn out;\n\t}\n}\n\npub struct ReleasedCBytes {\n\tptr: mem.Ptr<Byte>,\n\tlen: Int\n}\n\nimplement core.Copy for ReleasedCBytes {\n}\n\nimplement ReleasedCBytes {\n\tpub fn data(self: &ReleasedCBytes) nothrow -> mem.Ptr<Byte> {\n\t\treturn self.ptr;\n\t}\n\tpub fn size(self: &ReleasedCBytes) nothrow -> Int {\n\t\treturn self.len;\n\t}\n}\n\npub struct OwnedCBytesProbe {\n\tptr: mem.Ptr<Byte>,\n\tlen: Int\n}\n\nimplement core.Destructible for OwnedCBytesProbe {\n\tpub fn destroy(var self: OwnedCBytesProbe) nothrow -> Void {\n\t\tval is_null = unsafe { mem.ptr_is_null<type Byte>(self.ptr) };\n\t\tif is_null {\n\t\t\treturn;\n\t\t}\n\t}\n}\n\nimplement OwnedCBytesProbe {\n\tpub fn get(self: &OwnedCBytesProbe) nothrow -> ReleasedCBytes {\n\t\treturn ReleasedCBytes(ptr = self.ptr, len = self.len);\n\t}\n\tpub fn release(var self: OwnedCBytesProbe) nothrow -> ReleasedCBytes {\n\t\tvar drained = mem.rawbuffer_empty<type Byte>();\n\t\tval null_ptr = mem.rawbuffer_ptr<type Byte>(drained);\n\t\tval out = mem.replace<type mem.Ptr<Byte> >(self.ptr, null_ptr);\n\t\treturn ReleasedCBytes(ptr = out, len = self.len);\n\t}\n}\n\n// ── Scope types: helper RETAINS ownership; body gets &mut ──\n\npub struct CArgvProbe {\n\targv: mem.Ptr<mem.Ptr<Byte> >,\n\targc: Int\n}\n\nimplement core.Copy for CArgvProbe {\n}\n\nimplement CArgvProbe {\n\tpub fn vector(self: &CArgvProbe) nothrow -> mem.Ptr<mem.Ptr<Byte> > {\n\t\treturn self.argv;\n\t}\n\tpub fn count(self: &CArgvProbe) nothrow -> Int {\n\t\treturn self.argc;\n\t}\n}\n\npub struct CStringScopeProbe {\n\tpins: Array<String>\n}\n\nimplement core.Destructible for CStringScopeProbe {\n\tpub fn destroy(var self: CStringScopeProbe) nothrow -> Void {\n\t}\n}\n\nimplement CStringScopeProbe {\n\tpub fn cstr(self: &mut CStringScopeProbe, s: &String) nothrow -> core.Result<mem.Ptr<Byte>, CStringError> {\n\t\tself.pins.push(s.clone());\n\t\tval b = zero_byte();\n\t\treturn core.Result::Ok(unsafe { mem.ptr_from_ref<type Byte>(b) });\n\t}\n\tpub fn cstr_unsafe(self: &mut CStringScopeProbe, s: &String) nothrow -> mem.Ptr<Byte> {\n\t\tval b = zero_byte();\n\t\treturn unsafe { mem.ptr_from_ref<type Byte>(b) };\n\t}\n\tpub fn argv(self: &mut CStringScopeProbe, xs: &Array<String>) nothrow -> core.Result<CArgvProbe, CStringError> {\n\t\tval b = zero_byte();\n\t\tvar one = unsafe { mem.ptr_from_ref<type Byte>(b) };\n\t\tval vp = unsafe { mem.ptr_from_ref<type mem.Ptr<Byte> >(one) };\n\t\treturn core.Result::Ok(CArgvProbe(argv = vp, argc = xs.len()));\n\t}\n}\n\npub fn with_cstring_scope_probe<T, F>(body: F) nothrow -> T require F is core.Fn1<&mut CStringScopeProbe, T> {\n\tvar pins0: Array<String> = [];\n\tvar s = CStringScopeProbe(pins = move pins0);\n\treturn body.call(s);\n}\n\npub fn with_cstring_scope_throw_probe<T, F>(body: F) -> T require F is core.FnThrow1<&mut CStringScopeProbe, T> {\n\tvar pins0: Array<String> = [];\n\tvar s = CStringScopeProbe(pins = move pins0);\n\treturn body.call(s);\n}\n\n// ── compile-time instantiation of the THROWING family (pub, linkable) ──\n\npub fn exercise_throwing() -> Int {\n\tval src = "t";\n\tval t2: core.CallbackThrow2<mem.Ptr<Byte>, Int, Int> =\n\t\tcore.callback_throw2(|p: mem.Ptr<Byte>, n: Int| => { n });\n\tval a = with_bytes_throw_probe<type Int, core.CallbackThrow2<mem.Ptr<Byte>, Int, Int> >(src, t2);\n\n\tval t1: core.CallbackThrow1<mem.Ptr<Byte>, Int> =\n\t\tcore.callback_throw1(|p: mem.Ptr<Byte>| => { 1 });\n\tval r1 = with_cstr_throw_probe<type Int, core.CallbackThrow1<mem.Ptr<Byte>, Int> >(src, t1);\n\n\tval t2b: core.CallbackThrow2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback_throw2(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>| => { 2 });\n\tval r2 = with_cstr2_throw_probe<type Int, core.CallbackThrow2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, t2b);\n\n\tval t3: core.CallbackThrow3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback_throw3(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, r: mem.Ptr<Byte>| => { 3 });\n\tval r3 = with_cstr3_throw_probe<type Int, core.CallbackThrow3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, t3);\n\n\tval t4: core.CallbackThrow4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback_throw4(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, r: mem.Ptr<Byte>, w: mem.Ptr<Byte>| => { 4 });\n\tval r4 = with_cstr4_throw_probe<type Int, core.CallbackThrow4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, src, t4);\n\n\tval ts: core.CallbackThrow1<&mut CStringScopeProbe, Int> =\n\t\tcore.callback_throw1(|sc: &mut CStringScopeProbe| => { 5 });\n\tval r5 = with_cstring_scope_throw_probe<type Int, core.CallbackThrow1<&mut CStringScopeProbe, Int> >(ts);\n\n\tval k1 = match r1 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\tval k2 = match r2 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\tval k3 = match r3 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\tval k4 = match r4 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\treturn a + k1 + k2 + k3 + k4 + r5;\n}\n\n// ── entry: exercise nothrow families end-to-end ──\n\npub fn main() nothrow -> Int {\n\tval src = "probe";\n\tval cb2: core.Callback2<mem.Ptr<Byte>, Int, Int> =\n\t\tcore.callback2(|p: mem.Ptr<Byte>, len: Int| => { len });\n\tval n = with_bytes_probe<type Int, core.Callback2<mem.Ptr<Byte>, Int, Int> >(src, cb2);\n\n\tval cb1: core.Callback1<mem.Ptr<Byte>, Int> =\n\t\tcore.callback1(|p: mem.Ptr<Byte>| => { 1 });\n\tval r = with_cstr_probe<type Int, core.Callback1<mem.Ptr<Byte>, Int> >(src, cb1);\n\tval k = match r {\n\t\tcore.Result::Ok(v) => { v },\n\t\tcore.Result::Err(e) => { 0 },\n\t};\n\n\tval cc2: core.Callback2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback2(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>| => { 2 });\n\tval rc2 = with_cstr2_probe<type Int, core.Callback2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, cc2);\n\tval kc2 = match rc2 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\n\tval cc3: core.Callback3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback3(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, w: mem.Ptr<Byte>| => { 3 });\n\tval rc3 = with_cstr3_probe<type Int, core.Callback3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, cc3);\n\tval kc3 = match rc3 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\n\tval cc4: core.Callback4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback4(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, w: mem.Ptr<Byte>, z: mem.Ptr<Byte>| => { 4 });\n\tval rc4 = with_cstr4_probe<type Int, core.Callback4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, src, cc4);\n\tval kc4 = match rc4 { core.Result::Ok(v) => { v }, core.Result::Err(e) => { 0 }, };\n\n\tval cbu2: core.Callback2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback2(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>| => { 2 });\n\tval u2 = with_cstr2_unsafe_probe<type Int, core.Callback2<mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, cbu2);\n\n\tval cbu3: core.Callback3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback3(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, w: mem.Ptr<Byte>| => { 3 });\n\tval u3 = with_cstr3_unsafe_probe<type Int, core.Callback3<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, cbu3);\n\n\tval cbu4: core.Callback4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> =\n\t\tcore.callback4(|p: mem.Ptr<Byte>, q: mem.Ptr<Byte>, w: mem.Ptr<Byte>, z: mem.Ptr<Byte>| => { 4 });\n\tval u4 = with_cstr4_unsafe_probe<type Int, core.Callback4<mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, mem.Ptr<Byte>, Int> >(src, src, src, src, cbu4);\n\n\tval cbp: core.Callback1<mem.Ptr<Byte>, mem.Ptr<Byte> > =\n\t\tcore.callback1(|p: mem.Ptr<Byte>| => { p });\n\tvar owned = OwnedCStrProbe(\n\t\tptr = with_cstr_unsafe_probe<type mem.Ptr<Byte>, core.Callback1<mem.Ptr<Byte>, mem.Ptr<Byte> > >(src, cbp));\n\tval raw = owned.release();\n\n\tvar ob = OwnedCBytesProbe(ptr = raw, len = 5);\n\tval gb = ob.get();\n\tval gblen = gb.size();\n\tval rb = ob.release();\n\tval rblen = rb.size();\n\n\tval cbs: core.Callback1<&mut CStringScopeProbe, Int> =\n\t\tcore.callback1(|sc: &mut CStringScopeProbe| => {\n\t\t\tval q = sc.cstr_unsafe("x");\n\t\t\tval av = sc.argv(["a"]);\n\t\t\tval ac = match av { core.Result::Ok(v) => { v.count() }, core.Result::Err(e) => { 0 }, };\n\t\t\t1 + ac\n\t\t});\n\tval scoped = with_cstring_scope_probe<type Int, core.Callback1<&mut CStringScopeProbe, Int> >(cbs);\n\n\tif n == 5 { return (k - 1) + (kc2 - 2) + (kc3 - 3) + (kc4 - 4) + (u2 - 2) + (u3 - 3) + (u4 - 4) + (gblen - 5) + (rblen - 5) + (scoped - 2); }\n\treturn 1;\n}\n'


def test_b5_ffi_signature_probes_compile_and_run(tmp_path: Path) -> None:
	src = tmp_path / "main.drift"
	src.write_text(PROBE_SRC)
	out_bin = tmp_path / "bin"
	res = subprocess.run(
		[sys.executable, "-m", "lang.driftc.driftc", "--dev", "--allow-unsafe",
		 "--stdlib-root", str(ROOT / "stdlib"),
		 str(src), "--entry", "main::main", "-o", str(out_bin)],
		cwd=ROOT, capture_output=True, text=True,
		timeout=sanitizer_timeout(180),
	)
	assert res.returncode == 0, (
		"B5 API signature probes must compile+link cleanly:\n"
		f"{res.stdout}\n---\n{res.stderr[:2000]}"
	)
	run = subprocess.run([str(out_bin)], capture_output=True, text=True,
		timeout=sanitizer_timeout(60))
	assert run.returncode == 0, (
		f"probe binary must run clean: exit={run.returncode}\n{run.stderr[:500]}"
	)
